-- L22-l1-otakudle-facts-corrections.sql (lane otkdata, run O1, audit 06 of 2026-11-08 validated by the owner on 2026-11-09; generated by scripts/anime/a2/corrections/gen.mjs from spec-l22.json, do not edit by hand)
--
-- What:   126 values of character_facts (otakudle), each guarded on the value L13 wrote (L18 for King Bradley) and each with its source in entity_sources (the Wikipedia or Fandom page read on 2026-11-09, source_ref = its revision id):
--         gender 2 (Captain Ginyu male, Neferpitou null), role_at_debut 21 (OT2 to OT9 and the sample, plus the 9 missing roles), species 27 (the "as first met" rule, the 9 missing,
--         Kagura and Kamui "yato", Inuyasha "half-demon", Puar, Oolong and Korin "animal"), voice_actor_ja 76 (D-5: the Japanese voice actor of the first TV anime series: Tokyo Revengers 12, Fullmetal Alchemist 7,
--         Hunter x Hunter 8 (the 1999 series), Raditz, Aqua, Tohru, Giorno, Joseph, Dio, Kogoro, Kyo, Jotaro, Josuke, Tae; Dandadan and Blue Lock were in Japanese script; surname-first names of Re:Zero and Sword Art Online reordered).
--         featured: rimuru-tempest false -> true, haise-sasaki true -> false, gohan false -> true, goku false -> true, frieza false -> true, piccolo false -> true, nezuko-kamado false -> true, inosuke-hashibira false -> true, alphonse-elric false -> true (OT-D2, OT-D3). A new facts row: ken-kaneki (OT-D3, from its own pages; it differs from Haise Sasaki's row in species: "human" as first met, Haise holds "ghoul").
--         OT-D4: 38 source rows for the roles that rested on the site's own data. OT-D1: hisoka-morrow is excluded from the pool (dle_curation).
--         Answers: the featured characters with a complete row are possible answers: jinbe, jewelry-bonney, kozuki-oden, vegapunk, toshiro-hitsugaya, byakuya-kuchiki, kenpachi-zaraki, mayuri-kurotsuchi, gotenks, kyo-sohma, jotaro-kujo, josuke-higashikata, ken-kaneki, gohan, goku, frieza, piccolo, nezuko-kamado, inosuke-hashibira, alphonse-elric.
--         Not applied, listed below as commented blocks (the audit leaves them open or the source says otherwise):
--   OT-D7a: Obito (role antagonist: his debut, chapter 239, is the heroic Kakashi Gaiden flashback), Uryu (role main, introduced as Ichigo's rival), Garp (role antagonist) and Sukuna (species human; JJK says cursed-spirit): the audit leaves it to the owner, case by case. Nothing is written.
-- (no statement until the owner decides each case)
--   OT-e1: Secre Swallowtail species: "human" today, "bird (Nero), as first met" only if the rule is applied strictly; the audit gives no recommendation.
-- update public.character_facts f set species = 'bird' from public.characters c join public.groups g on g.id = c.group_id and g.site_id = 'anime' and g.slug = 'black-clover' where f.character_id = c.id and c.slug = 'secre-swallowtail' and f.species = 'human';
--   OT-D5b: Dio Brando: Takehito Koyasu is written (first TV series, 2012). Akito, Kyoko, Momiji, Hiro (Fruits Basket) look like drama CD casting in the stored values; the cast list read is ambiguous, so nothing is written for them.
-- (no statement)
--   OT-H11b: Hunter x Hunter: Meruem, Pariston, Alluka, Komugi, Neferpitou (Chimera Ant arc and later) have no 1999 cast; their 2011 voice actor stays. Chrollo (Yoshikazu Nagano), Feitan (Akari Hibino), Illumi, Machi, Phinks, Uvogin, Zeno already hold their 1999 actor, which the cast list confirms; Biscuit keeps the Greed Island OVA actor.
-- (no statement)
--   OT-gender: Rimuru Tempest has no gender (as first met, a slime) and the column accepts only female or male: he is featured but cannot be an answer until the owner allows "neutral" in character_facts.gender (a constraint change, not made here).
-- (no statement)
--         Nothing else: no other column, no kpop row. updated_at is not touched, so the rollback is exact.
-- Needs:  023, L04, L13 (the 750 character_facts rows), L18 (it spelled "homunculu" as "homunculus": King Bradley is guarded on that value), 019 (dle_curation, dle_refresh_entities).
-- WHEN:   apply by the owner after a backup, just after 00:30 UTC, never between 23:50 and 00:30 UTC, never during a build. The first statements read dle_schedule for today and the next 7 days and abort
--         (nothing is written) if a character that stops being a possible answer is scheduled there (haise-sasaki); ORCH reads those 7 days in production before the owner applies.
--         A guess is stored as the entity id only and its colours are computed on every read, so a game in progress is recoloured at once; the snapshot dle_entities is refreshed in the same transaction.
--         The pool of answers changes (20 characters become possible answers, 1 stops): the next dle_daily_maintenance sees a new pool hash and rebuilds the bank (L18: it keeps today and the 7 days after it).
-- Verify: select count(*) from public.dle_entities where game_id = 'otakudle' and can_be_target and in_pool;   expect 204
-- Verify: select count(*) from public.character_facts where featured;   expect 208
-- Verify: select count(*) from public.character_facts where role_at_debut is not null;   expect 725
-- Verify: select f.gender from public.character_facts f join public.characters c on c.id = f.character_id where c.slug = 'captain-ginyu';   expect male
-- Verify: select f.voice_actor_ja from public.character_facts f join public.characters c on c.id = f.character_id where c.slug = 'raditz';   expect Shigeru Chiba
-- Verify: select count(*) from public.character_facts f join public.characters c on c.id = f.character_id where c.slug = 'ken-kaneki';   expect 1
-- Undo:   L22-l1-otakudle-facts-corrections.rollback.sql (restores the values of L13 and their sources).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing; a row that already moved to another value is left alone (warning).

do $o1l22$
begin
perform set_config('lock_timeout', '5s', true);
perform set_config('client_min_messages', 'warning', true);


begin
  if to_regclass('public.character_facts') is null or to_regclass('public.entity_sources') is null then
    raise exception 'L22: 023 and L13 must be applied first';
  end if;
  if (select count(*) from public.character_facts) < 750 then
    raise exception 'L22: the 750 character_facts rows of L13 are not all there (apply L13 first)';
  end if;
end;

-- Precheck of the next 7 days (AUDITS-COMMON): haise-sasaki stop being a possible answer of otakudle, so none of them may be today's answer or scheduled in the next 7 days; otherwise the file aborts and is applied after that day.
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null then
    for r in
      select g.id as game_id, c.slug, s.bank_day
      from public.dle_games g
      join public.dle_schedule s on s.game_id = g.id
      join public.characters c on c.id::text = s.entity_id
      join public.groups gr on gr.id = c.group_id and gr.site_id = 'anime'
      where g.id = 'otakudle' and g.epoch is not null and (gr.slug, c.slug) in (('tokyo-ghoul', 'haise-sasaki'))
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
      union all
      select g.id, c.slug, null from public.dle_games g join public.dle_daily_stats d on d.game_id = g.id and d.play_date >= public.dle_utc_date(now())
      join public.characters c on c.id::text = d.entity_id join public.groups gr on gr.id = c.group_id and gr.site_id = 'anime'
      where g.id = 'otakudle' and (gr.slug, c.slug) in (('tokyo-ghoul', 'haise-sasaki'))
    loop
      raise exception 'L22: % is the answer of % (bank day %) today or in the next 7 days: apply this file after that day', r.slug, r.game_id, coalesce(r.bank_day::text, 'served today');
    end loop;
  end if;
end;


