  news constant jsonb := '[
{"series":"tokyo-ghoul","slug":"ken-kaneki","gender":"male","species":"human","role_at_debut":"main","first_appearance":"Chapter 1 / Episode 1","voice_actor_ja":"Natsuki Hanae","featured":true}
